// Prototype variant: compiled theme (src/theme.compiled.ts, generated by `emoji-styles theme compile`) and the catalog-free entries.
import {CompiledEmojiToken} from 'react-emoji-styles/compiled';
import 'react-emoji-styles/styles.css';
import {compiledEmojiTheme} from './theme.compiled';
import {Page} from './page';
export default function App(){return <Page renderEmoji={item=><CompiledEmojiToken token={item.token} theme={compiledEmojiTheme} size={20} lazy={false}/>}/>;}
